from __future__ import annotations

import json
import os
import sys
import time
import typing as _t
import urllib.error
import urllib.request


_DEFAULT_BASE_URL = \"https://api.openai.com/v1\"
_RESPONSES_PATH = \"/responses\"
_DEFAULT_MODEL = \"gpt-4o-mini\"
_USER_AGENT = \"openai-client-stdlib/0.1\"


class OpenAIAPIError(RuntimeError):
    def __init__(self, status: int, message: str, *, type: str | None = None, code: _t.Any = None):
        super().__init__(f\"HTTP {status}: {message}\")
        self.status = status
        self.message = message
        self.type = type
        self.code = code


class OpenAIClient:
    def __init__(
        self,
        api_key: str | None = None,
        *,
        base_url: str = _DEFAULT_BASE_URL,
        timeout: float = 60.0,
        organization: str | None = None,
        project: str | None = None,
    ) -> None:
        self.api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
        if not self.api_key:
            raise ValueError(\"OPENAI_API_KEY is not set and no api_key was provided.\")
        self.base_url = base_url.rstrip(\"/\")
        self.timeout = float(timeout)
        self.organization = organization or os.environ.get(\"OPENAI_ORG_ID\")
        self.project = project or os.environ.get(\"OPENAI_PROJECT_ID\")
        self._opener = urllib.request.build_opener()

    def prompt_text(
        self,
        prompt: str,
        *,
        model: str = _DEFAULT_MODEL,
        extra: dict | None = None,
        timeout: float | None = None,
        retries: int = 2,
        retry_backoff: float = 0.8,
    ) -> str:
        payload = {\"model\": model, \"input\": prompt}
        if extra:
            payload.update(extra)
        resp = self._post_json(
            _RESPONSES_PATH,
            payload,
            timeout=timeout,
            retries=retries,
            retry_backoff=retry_backoff,
        )
        return _extract_output_text(resp)

    def create_response(
        self,
        *,
        model: str,
        input: _t.Any = None,
        extra: dict | None = None,
        timeout: float | None = None,
        retries: int = 2,
        retry_backoff: float = 0.8,
    ) -> dict:
        payload = {\"model\": model}
        if input is not None:
            payload[\"input\"] = input
        if extra:
            payload.update(extra)
        return self._post_json(
            _RESPONSES_PATH,
            payload,
            timeout=timeout,
            retries=retries,
            retry_backoff=retry_backoff,
        )

    def stream_prompt_text(
        self,
        prompt: str,
        *,
        model: str = _DEFAULT_MODEL,
        extra: dict | None = None,
        timeout: float | None = None,
    ) -> _t.Iterator[str]:
        payload = {\"model\": model, \"input\": prompt, \"stream\": True}
        if extra:
            payload.update(extra)
        url = self.base_url + _RESPONSES_PATH
        headers = self._default_headers(stream=True)
        data = json.dumps(payload).encode(\"utf-8\")
        req = urllib.request.Request(url=url, data=data, headers=headers, method=\"POST\")

        try:
            with self._opener.open(req, timeout=(timeout or self.timeout)) as resp:
                buf = b\"\"
                while True:
                    chunk = resp.read(1 << 14)
                    if not chunk:
                        if buf:
                            for out in _iter_sse_lines(buf):
                                if out is not None:
                                    yield out
                        break
                    buf += chunk
                    for out in _iter_sse_lines(buf):
                        if out is None:
                            continue
                        yield out
                    buf = _SSE_STATE.remainder
        except urllib.error.HTTPError as e:
            _raise_from_http_error(e)

    # ----------------------------- Internal helpers -----------------------------
    def _post_json(
        self,
        path: str,
        payload: dict,
        *,
        timeout: float | None = None,
        retries: int = 0,
        retry_backoff: float = 0.8,
    ) -> dict:
        url = self.base_url + path
        data = json.dumps(payload).encode(\"utf-8\")
        headers = self._default_headers(stream=False)
        req = urllib.request.Request(url=url, data=data, headers=headers, method=\"POST\")

        attempt = 0
        while True:
            try:
                with self._opener.open(req, timeout=(timeout or self.timeout)) as resp:
                    body = resp.read()
                    return _json_or_error(body, status=getattr(resp, \"status\", 200))
            except urllib.error.HTTPError as e:
                status = e.code
                if attempt < retries and status in (429, 500, 502, 503, 504):
                    sleep = (retry_backoff ** attempt) * 1.0 + (0.05 * attempt)
                    time.sleep(min(2.0, sleep))
                    attempt += 1
                    continue
                _raise_from_http_error(e)

    def _default_headers(self, *, stream: bool) -> dict:
        headers = {
            \"Authorization\": f\"Bearer {self.api_key}\",
            \"Content-Type\": \"application/json\",
            \"Accept\": \"text/event-stream\" if stream else \"application/json\",
            \"User-Agent\": _USER_AGENT,
        }
        if self.organization:
            headers[\"OpenAI-Organization\"] = self.organization
        if self.project:
            headers[\"OpenAI-Project\"] = self.project
        return headers


# ------------------------------- JSON utilities --------------------------------

def _json_or_error(body: bytes, *, status: int) -> dict:
    try:
        data = json.loads(body.decode(\"utf-8\"))
    except Exception:
        raise OpenAIAPIError(status, body.decode(\"utf-8\", errors=\"replace\"))

    if 200 <= status < 300:
        return data

    if isinstance(data, dict) and \"error\" in data:
        err = data[\"error\"] or {}
        raise OpenAIAPIError(status, str(err.get(\"message\") or \"API error\"), type=err.get(\"type\"), code=err.get(\"code\"))
    raise OpenAIAPIError(status, json.dumps(data))


def _raise_from_http_error(e: urllib.error.HTTPError) -> \"noreturn\":  # type: ignore[valid-type]
    status = getattr(e, \"code\", 0) or 0
    try:
        body = e.read()
    except Exception:
        body = b\"\"
    try:
        data = json.loads(body.decode(\"utf-8\")) if body else None
    except Exception:
        data = None
    if isinstance(data, dict) and \"error\" in data:
        err = data[\"error\"] or {}
        raise OpenAIAPIError(status, str(err.get(\"message\") or \"HTTP error\"), type=err.get(\"type\"), code=err.get(\"code\"))
    msg = (body.decode(\"utf-8\", errors=\"replace\") if body else str(e))
    raise OpenAIAPIError(status, msg)


def _extract_output_text(resp: dict) -> str:
    if isinstance(resp, dict) and isinstance(resp.get(\"output_text\"), str):
        return resp[\"output_text\"]

    texts: list[str] = []

    def walk(obj: _t.Any) -> None:
        if isinstance(obj, dict):
            for k in (\"output_text\", \"text\", \"content\"):
                if k in obj and isinstance(obj[k], str):
                    texts.append(obj[k])
            for v in obj.values():
                walk(v)
        elif isinstance(obj, list):
            for v in obj:
                walk(v)

    if \"output\" in resp:
        walk(resp[\"output\"])
    if not texts:
        walk(resp)

    combined = \"\".join(texts).strip()
    return combined if combined else json.dumps(resp)


# --------------------------- Streaming (SSE) utilities --------------------------

class _SSEState:
    def __init__(self) -> None:
        self.remainder: bytes = b\"\"


_SSE_STATE = _SSEState()


def _iter_sse_lines(buffer: bytes) -> _t.Iterator[str | None]:
    \"\"\"Consume complete SSE \"data:\" frames from buffer and yield text deltas.

    Returns None once to indicate that the caller should preserve current
    remainder in "'`_SSE_STATE.remainder`. This function updates the module-level
    remainder to any trailing partial frame.
    """
    data = _SSE_STATE.remainder + buffer
    parts = data.split(b"'"\\n\\n\")
    complete, remainder = parts[:-1], parts[-1]
    _SSE_STATE.remainder = remainder

    yielded_any = False
    for part in complete:
        for line in part.splitlines():
            line = line.strip()
            if not line or not line.startswith(b\"data:\"):
                continue
            payload = line[5:].strip()
            if payload == b\"[DONE]\":
                continue
            if not payload:
                continue
            try:
                event = json.loads(payload.decode(\"utf-8\"))
            except Exception:
                continue

            etype = event.get(\"type\")
            if etype == \"response.output_text.delta\":
                delta = event.get(\"delta\")
                if isinstance(delta, str) and delta:
                    yielded_any = True
                    yield delta
            elif etype in (\"response.stream.completed\", \"response.completed\"):
                continue

    if remainder and not yielded_any:
        yield None


# --------------------------------- CLI support ---------------------------------

_HELP = (
    \"Usage: OPENAI_API_KEY=sk-... python3 openai_client.py 'prompt text'\\n\"
    \"       Add --stream to stream output. Optional --model MODEL.\\n\"
    \"Examples:\\n\"
    \"  python3 openai_client.py 'Say hello'\\n\"
    \"  python3 openai_client.py --stream 'Write a limerick'\\n\"
    \"  python3 openai_client.py --model gpt-4o-mini 'Quick test'\\n\"
)


def _cli(argv: list[str]) -> int:
    if not argv or argv[0] in {\"-h\", \"--help\"}:
        print(_HELP)
        return 0

    stream = False
    model = _DEFAULT_MODEL
    args = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == \"--stream\":
            stream = True
            i += 1
        elif a == \"--model\" and i + 1 < len(argv):
            model = argv[i + 1]
            i += 2
        else:
            args.append(a)
            i += 1

    if not args:
        print(\"Error: missing prompt. See --help.\", file=sys.stderr)
        return 2
    prompt = \" \".join(args)

    try:
        client = OpenAIClient()
    except ValueError as e:
        print(str(e), file=sys.stderr)
        return 2

    try:
        if stream:
            for chunk in client.stream_prompt_text(prompt, model=model):
                if chunk is not None:
                    print(chunk, end=\"\", flush=True)
            print()
        else:
            out = client.prompt_text(prompt, model=model)
            print(out)
    except OpenAIAPIError as e:
        print(f\"API error: {e}\", file=sys.stderr)
        return 1
    except KeyboardInterrupt:
        print(\"\\nCancelled.\")
        return 130
    return 0


if __name__ == \"__main__\":
    raise SystemExit(_cli(sys.argv[1:]))
